// Package target: the output formats of compiled instances (Target), and
// what they share: where their files are (ProjectsDir, ProjectDir,
// InstanceDir), the mark of a generated file (Generated), the checks of
// their options.
package target

import (
	"errors"
	"fmt"
	"io/fs"
	"maps"
	"path"
	"slices"
	"strings"

	"github.com/okdp/okdp-compiler/internal/graph"
	"github.com/okdp/okdp-compiler/internal/okdp"
)

// Target: an output format: the files of compiled instances, path ->
// content, every path under ProjectsDir, all a deployer reads of the
// compiled tree. results are those of every instance of their namespaces,
// g their graph (graph.New).
type Target interface {
	Files(results []*okdp.Result, g *graph.Graph) (map[string][]byte, error)
}

// Generated: the first line of a file the compiler writes for a deployer,
// Go's mark of a generated file, which GitHub, linters and editors know.
const Generated = "# Code generated by okdp-compile. DO NOT EDIT.\n"

// ProjectsDir: the directory of every file of a target, projects/.
const ProjectsDir = "projects"

// ProjectDir: projects/<namespace>, the files of a namespace's instances.
func ProjectDir(namespace string) string { return path.Join(ProjectsDir, namespace) }

// InstanceDir: projects/<namespace>/instances/<release>, an instance's
// umbrella chart, in every target.
func InstanceDir(namespace, release string) string {
	return path.Join(ProjectDir(namespace), "instances", release)
}

// CheckPrefix: nil when prefix, the path of the tree in the repository a
// deployer reads (a target's PathPrefix, of the field named field), is ""
// or a relative path without an empty, . or .. segment.
func CheckPrefix(field, prefix string) error {
	if prefix != "" && !fs.ValidPath(prefix) || prefix == "." {
		return fmt.Errorf("%s %q: the path of the tree in the repository, relative, without an empty, . or .. segment", field, prefix)
	}
	return nil
}

// CheckQuoted: nil when s, a value of the field named field written
// between double quotes, holds no quote, backslash or newline.
func CheckQuoted(field, s string) error {
	if strings.ContainsAny(s, "\"\\\n") {
		return fmt.Errorf("%s %q: holds a quote, a backslash or a newline", field, s)
	}
	return nil
}

// ReleaseError: a release name in two namespaces or more, which the
// deployer targets refuse (Releases): their objects, named after the
// releases, share one namespace.
type ReleaseError struct {
	Release    string
	Namespaces []string // in name order
}

func (e *ReleaseError) Error() string {
	ns := make([]string, len(e.Namespaces))
	for i, n := range e.Namespaces {
		ns[i] = fmt.Sprintf("%q", n)
	}
	return fmt.Sprintf("release %q is in namespaces %s and %s", e.Release, strings.Join(ns[:len(ns)-1], ", "), ns[len(ns)-1])
}

// Releases: nil when no release name is in two namespaces of results:
// else a *ReleaseError per release, in name order.
func Releases(results []*okdp.Result) error {
	namespaces := map[string][]string{}
	for _, res := range results {
		namespaces[res.Release] = append(namespaces[res.Release], res.Namespace)
	}
	var errs []error
	for _, release := range slices.Sorted(maps.Keys(namespaces)) {
		if ns := namespaces[release]; len(ns) > 1 {
			slices.Sort(ns)
			errs = append(errs, &ReleaseError{Release: release, Namespaces: ns})
		}
	}
	return errors.Join(errs...)
}

// UniqueReleases: Releases, each error naming objects, the objects of a
// target named after the releases, which share one namespace.
func UniqueReleases(results []*okdp.Result, objects string) error {
	err := Releases(results)
	if err == nil {
		return nil
	}
	var errs []error
	for _, e := range err.(interface{ Unwrap() []error }).Unwrap() {
		errs = append(errs, fmt.Errorf("%w: %s need distinct names", e, objects))
	}
	return errors.Join(errs...)
}

// Lines: a file built line by line (Add).
type Lines struct{ strings.Builder }

// Add: a line, format and args as fmt.Sprintf's.
func (l *Lines) Add(format string, args ...any) {
	fmt.Fprintf(&l.Builder, format, args...)
	l.WriteByte('\n')
}
